template <typename N>
template <typename Polygon>
typename Earcut<N>::Node* Earcut<N>::eliminateHoles(const Polygon& points, Node* outerNode) {
    std::vector<Node*> queue;

    for (std::size_t i = 1, start = points[0].size(), end = 0; i < points.size(); i++) {
        end = start + points[i].size();
        Node* list = linkedList(points[i], start, end, false);
        if (list) {
            if (list == list->next) list->steiner = true;
            queue.push_back(getLeftmost(list));
        }
        start = end;
    }
    std::sort(queue.begin(), queue.end(), [](const Node* a, const Node* b) { return a->x < b->x; });

    // process holes from left to right
    for (Node* hole : queue) outerNode = eliminateHole(hole, outerNode);

    return outerNode;
}
