template <typename N>
template <typename Ring>
double Earcut<N>::signedArea(const Ring& points, const std::size_t start, const std::size_t end) const {
    double sum = 0;
    for (std::size_t i = start, j = end - 1; i < end; i++) {
        sum += (static_cast<double>(points[j][0]) - static_cast<double>(points[i][0])) * (static_cast<double>(points[i][1]) + static_cast<double>(points[j][1]));
        j = i;
    }
    return sum;
}
