}

pub struct Earcut {
    pub indices: Vec<u32>,
    nodes: Vec<Node>,
    inv_size: f64,
    min_x: f64,
    min_y: f64,
}

pub fn earcut(polygon: &[Vec<(f64, f64)>]) -> Vec<u32> {
    let mut e = Earcut {
        indices: Vec::new(),
        nodes: Vec::new(),
        inv_size: 0.0,
        min_x: 0.0,
        min_y: 0.0,
    };
    e.run(polygon);
    e.indices
}
