fn run(&mut self, points: &[Vec<(f64, f64)>]) {
    if points.is_empty() { return; }
    let mut len = 0usize;
    for ring in points { len += ring.len(); }

    let outer_node = self.linked_list(&points[0], 0, true);

    let mut outer_node = match outer_node {
        Some(n) => n,
        None => return,
    };
    if self.nodes[outer_node].prev == self.nodes[outer_node].next { return; }

    if points.len() > 1 {
        outer_node = self.eliminate_holes(points, outer_node);
    }

    if len > 80 {
        let mut min_x = points[0][0].0;
        let mut min_y = points[0][0].1;
        let mut max_x = min_x;
        let mut max_y = min_y;
        for ring in points {
            for p in ring {
                if p.0 < min_x { min_x = p.0; }
                if p.1 < min_y { min_y = p.1; }
                if p.0 > max_x { max_x = p.0; }
                if p.1 > max_y { max_y = p.1; }
            }
        }
        self.min_x = min_x;
        self.min_y = min_y;
        let size = (max_x - min_x).max(max_y - min_y);
        self.inv_size = if size != 0.0 { 32767.0 / size } else { 0.0 };
    }

    self.earcut_linked(outer_node, 0);
}
