fn linked_list(&mut self, ring: &[(f64, f64)], start: usize, clockwise: bool) -> Option<usize> {
    let mut last: Option<usize> = None;
    let end = ring.len();

    if clockwise == (signed_area(ring) > 0.0) {
        for i in 0..end {
            last = Some(self.insert_node((start + i) as u32, ring[i].0, ring[i].1, last));
        }
    } else {
        for i in (0..end).rev() {
            last = Some(self.insert_node((start + i) as u32, ring[i].0, ring[i].1, last));
        }
    }

    if let Some(l) = last {
        if self.equals(l, self.nodes[l].next) {
            self.remove_node(l);
            last = Some(self.nodes[l].next);
        }
    }
    last
}
