fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
    let idx = self.nodes.len();
    self.nodes.push(Node { i, x, y, prev: idx, next: idx, z: 0, prev_z: NIL, next_z: NIL, steiner: false });
    if let Some(last) = last {
        let ln = self.nodes[last].next;
        self.nodes[idx].next = ln;
        self.nodes[idx].prev = last;
        self.nodes[ln].prev = idx;
        self.nodes[last].next = idx;
    }
    idx
}
