fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
    let mut p = outer_node;
    let hx = self.nodes[hole].x;
    let hy = self.nodes[hole].y;
    let mut qx = f64::NEG_INFINITY;
    let mut m: Option<usize> = None;

    loop {
        let pn = self.nodes[p].next;
        if hy <= self.nodes[p].y && hy >= self.nodes[pn].y && self.nodes[pn].y != self.nodes[p].y {
            let x = self.nodes[p].x + (hy - self.nodes[p].y) * (self.nodes[pn].x - self.nodes[p].x) / (self.nodes[pn].y - self.nodes[p].y);
            if x <= hx && x > qx {
                qx = x;
                if x == hx {
                    if hy == self.nodes[p].y { return Some(p); }
                    if hy == self.nodes[pn].y { return Some(pn); }
                }
                m = Some(if self.nodes[p].x < self.nodes[pn].x { p } else { pn });
            }
        }
        p = pn;
        if p == outer_node { break; }
    }

    let mut m = m?;
    if hx == qx { return Some(m); }

    let stop = m;
    let mut tan_min = f64::INFINITY;
    let mx = self.nodes[m].x;
    let my = self.nodes[m].y;

    p = self.nodes[m].next;
    while p != stop {
        if hx >= self.nodes[p].x && self.nodes[p].x >= mx && hx != self.nodes[p].x
            && point_in_triangle(
                if hy < my { hx } else { qx }, hy,
                mx, my,
                if hy < my { qx } else { hx }, hy,
                self.nodes[p].x, self.nodes[p].y) {
            let tan_cur = (hy - self.nodes[p].y).abs() / (hx - self.nodes[p].x);
            if (tan_cur < tan_min || (tan_cur == tan_min && self.nodes[p].x > self.nodes[m].x))
                && self.locally_inside(p, hole) {
                m = p;
                tan_min = tan_cur;
            }
        }
        p = self.nodes[p].next;
    }

    Some(m)
}
