/// Replicates glibc `atoi` semantics (`(int)strtol(s, NULL, 10)`): skip
/// leading whitespace, accept an optional sign, then consume digits; anything
/// else yields 0 and trailing garbage is ignored. Overflow clamps to the
/// `long` (i64) range like strtol, then truncates to `int` (i32).
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    let mut val: u64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val.saturating_mul(10).saturating_add((bytes[i] - b'0') as u64);
        // keep the accumulator inside the magnitude representable by i64+sign
        if val > i64::MAX as u64 + 1 {
            val = i64::MAX as u64 + 1;
        }
        i += 1;
    }
    let v: i64 = if neg {
        if val > i64::MAX as u64 {
            i64::MIN
        } else {
            -(val as i64)
        }
    } else if val > i64::MAX as u64 {
        i64::MAX
    } else {
        val as i64
    };
    v as i32
}

let n: i32 = if args.len() == 1 {
    2
} else {
    atoi(&args[1])
};

